// Simple math helpers.
export { div } from './divide.mjs';

export function add(a, b) {
  return a + b;
}

export function sub(a, b) {
  return a - b;
}

export function mul(a, b) {
  return a * b;
}

// Division helper, extracted for isolation of the zero-guard.
export function div(a, b) {
  if (b === 0) throw new Error('division by zero');
  return a / b;
}
